<script setup lang="ts">import{onMounted,ref}from"vue";import{PluginManagementService,type PluginRecord}from"../../../../frontend/src/services/plugin-management-service";const s=new PluginManagementService({requestId:crypto.randomUUID(),traceId:crypto.randomUUID(),identityId:"local-user",identityKind:"user",tenantId:"local-default"});const items=ref<PluginRecord[]>([]),id=ref(""),version=ref("1.0.0"),error=ref("");async function load(){items.value=(await s.list()).items}async function install(){try{await s.install(id.value,version.value);await load()}catch(e){error.value=e instanceof Error?e.message:"失败"}}async function act(p:PluginRecord,a:string){try{await s.action(p.plugin_id,a,a==='upgrade'?{version:version.value}:{});await load()}catch(e){error.value=e instanceof Error?e.message:"失败"}};onMounted(load);</script>
<template><section><strong>插件安全管理</strong><div><input v-model="id" placeholder="插件 ID"><input v-model="version"><button @click="install">安装</button></div><p v-for="p in items" :key="p.plugin_id">{{p.plugin_id}} {{p.version}} · {{p.status}} <button @click="act(p,p.status==='enabled'?'disable':'enable')">{{p.status==='enabled'?'停用':'启用'}}</button><button @click="act(p,'upgrade')">升级</button><button @click="act(p,'rollback')">回滚</button><button @click="act(p,'uninstall')">卸载</button></p><em>{{error}}</em></section></template>
